extern "C" float sqrtf(float);
void error(const char*);

inline float fast_recip_sqrt(float x)
{
  return 1.0F/(float)sqrtf(x);
}

class vector3d
{
public:
  float x, y, z;

  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d& operator=(const vector3d& v)
  { x = v.x; y = v.y; z = v.z; return *this; }
  inline vector3d& operator*=(float d)
  { x *= d; y *= d; z *= d; return *this; }
  inline float length2() const
  { return x*x + y*y + z*z; }
  inline vector3d& normalize()
  {
    float l2 = length2();
    if (l2>0.0001F*0.0001F)
      *this *= fast_recip_sqrt(l2);
    return *this;
  }
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
  void* my_thread;

  char* get_SP() const { return SP; }
  void move_SP(int n) { SP += n; }
  void pop(int n) { move_SP(-n); }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual ~function();
    virtual bool operator()(vm_stack& stack,entry_t entry) { return true; }
  };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result))) \
    error("script stack overflow")
#define SLF_DONE return true

class slf_normal3_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d v1;
  };
  virtual bool operator()(vm_stack& stack,entry_t entry)
  {
    SLF_PARMS;
    vector3d result = parms->v1.normalize();
    SLF_RETURN;
    SLF_DONE;
  }
};
